+  dissect_dcp_etsi(tvb, pinfo, tree, data);

-  sync = tvb_get_string_enc(pinfo->pool, tvb, 0, 2, ENC_ASCII);
-  dissector_try_string(dcp_dissector_table, (char*)sync, tvb, pinfo, dcp_tree, NULL);
   return TRUE;
 }

